INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2238e833-f668-4464-8b2c-3d4fbfaa30c2', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$111. óra: Projektóra$q$, $q$Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "180a9af4-52cb-4702-88be-2b56acf00e17", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "8b53f063-9a8b-498c-9e34-1e2f2801fd5e", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "9dea0f7a-90da-4ed8-a58f-7b6be5bbc7e2", "text": "A tető színét", "isCorrect": false}, {"id": "c1823ca0-a70f-4868-80a8-8fbd3e6ed1bc", "text": "Az épület magasságát", "isCorrect": false}, {"id": "61c8104e-028e-41a6-b198-1df50152172d", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "d6bb7942-7ae9-4a07-b9ef-d3ee161b2e79", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "c9b51e80-60c0-4614-ac0e-55a5bf5945ef", "text": "Igaz", "isCorrect": true}, {"id": "54098d0d-e5fe-4090-8da3-df1901e2aa18", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "de7d51b2-22eb-4238-b1ac-9c2ed4935a1d", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6ca82f3e-089b-4611-b5cc-4b4b95431fa9", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "de58937e-4774-4769-8843-315c9976bab3", "text": "Igaz", "isCorrect": true}, {"id": "9a879a1b-9e28-4f2f-877a-5ff2092d7a05", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2152b3e6-888b-4e86-b5cc-fa2cad8372ed", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "76aea87f-8e5d-47e2-8c3f-a3ac3dd3ca60", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "167e2e4e-f63f-43fe-91f2-eedf8a62d67b", "text": "Igaz", "isCorrect": true}, {"id": "5688e323-117c-48a5-bbf3-e9080aa7ec3d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8f423d57-af32-4b9c-bbfb-b8478ebe0f5b", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f602ce0b-9064-4a08-bb10-9c28023bc21f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$112. óra: Projektóra II.$q$, $q$Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "08db3bc5-6f87-4b9a-84d6-b3ac31c1bcbc", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "0e4d4c7b-9b19-4a4a-8ba7-09819a2fc19a", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "4932f90c-dedf-408b-8a27-4a79f4a315f1", "text": "Igaz", "isCorrect": true}, {"id": "a6d7a6f5-0d6c-429b-bdb6-cd71b447b554", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "47810580-cc4a-4166-aa56-7e7391029baf", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "cfa12b23-4ece-4484-a9e5-cb4774bc312b", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "e0028a75-745a-4b4f-9167-8ebd58f59f33", "text": "Gömbökből", "isCorrect": false}, {"id": "8e6c28fe-cef5-4bc4-a794-8cf27d28b72d", "text": "Kúpokból", "isCorrect": false}, {"id": "4c3faa71-8880-41de-afbe-e3568c37742e", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "08676234-2634-4d59-a6a7-630d58ca925e", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "00f9a1c1-9288-48c2-b3fb-404c68e972e6", "text": "Igaz", "isCorrect": true}, {"id": "683965f7-646b-433e-943f-995119df6dac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b6445a8a-0189-4d5a-9e52-e7ba5c293fad", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "f49e0164-d888-4bbd-9a56-e996e0e4dc97", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "ad17816b-c729-4ddd-ace9-cf1821ddf381", "text": "Igaz", "isCorrect": true}, {"id": "2f08f0a7-37ac-43d4-b9ff-a4bc62ecebe9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a7337975-9955-4f40-9a68-679cb902bb07", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4499a6f5-150a-4f60-a127-a7edbc943129', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$113. óra: Projektóra III.$q$, $q$Az elkészített projektek és makettek bemutatása, csoportértékelés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "cebf453c-6360-437d-be6d-830d79aa4e53", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "c0f13b03-a5d1-4e85-a314-c88222399b9f", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "5839a9ac-e8b6-48bc-bb9e-24d41f100cdc", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "54e616ee-e193-432a-96d9-eef6187ad632", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "1246f91e-b13c-4632-be47-8ea716c0381b", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "ee1e6891-3edd-4871-8fa2-ce38f086cf22", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "caa42824-0196-4119-ac48-b76779443839", "text": "Igaz", "isCorrect": true}, {"id": "1e78a4e5-c06f-4428-b24c-3c2202e07ab4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "495bdf0b-75ba-4fea-a020-c6914043cbb2", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "e9801dd4-5433-429e-957a-2899b3160986", "text": "Igaz", "isCorrect": true}, {"id": "592a08fd-5c7d-41f3-a9c2-6799efeb7dd3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "157b5dde-f72d-4a6f-b945-d7036ba6b56e", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "117f01d4-bace-4bd4-b22b-a3662ea5a94d", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "0df87c75-ce7d-4ec3-8751-e52e4885cb83", "text": "Igaz", "isCorrect": true}, {"id": "67e89da1-a158-40e3-846a-bb7f8a659fb7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2cecabc-e96d-4121-969c-c8573d653233", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "795b21d2-1418-4198-93e0-44b30635bfa9", "text": "Igaz", "isCorrect": true}, {"id": "ce5e7a35-2161-41bf-abe0-f27ac855064a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e34954d5-2c54-444c-a6b6-53b617418655", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4ba70bf1-9d22-4f1a-b3cd-ac7e523af3d3', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$114. óra: Összefoglalás$q$, $q$A Kerület, terület, felszín és térfogat fejezet összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "bcdd6b83-596e-423d-abdf-b0af05ff822b", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "fa59f528-4d01-426a-8a09-0fde72e305e8", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "3d37f447-a65a-4a21-ac43-65eb209ec362", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "2aff2a79-2110-45aa-b41a-bf8a3b739898", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "8b99a09e-3d12-473e-86bb-050645b72ca9", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "e1c3dc05-23fb-4ffc-aa77-1bbcb5adfc66", "text": "Igaz", "isCorrect": true}, {"id": "7dbb45af-456e-4ff8-90ab-185059794ef4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "deac43a5-7def-42d3-ab2b-c81464c2ad46", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "1c4e8714-700e-4762-9575-037669a97a17", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "28c8f847-c3c7-4e46-afb8-59824e3e378f", "text": "Igaz", "isCorrect": true}, {"id": "ac989f8c-90c5-46ca-ac20-66606e197762", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ba25e0cb-e42d-493e-92d8-7e34b133c3c6', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$115. óra: Gyakorlóóra$q$, $q$Gyakorló feladatsor önálló megoldása a mérések témakörben.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "d870cf0f-871b-4b0a-bb48-e54e144804b0", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "6d5eaf43-d9c7-4a76-9a62-8414551ec54e", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6b0c261b-6d21-4343-89fb-2101bf4ac168", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "646a7d2a-537b-4a34-8094-afb3d8090064", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "fdc5a4a2-96b2-4d57-9ddf-b11491d3e441", "text": "Igaz", "isCorrect": true}, {"id": "60b6c93c-4161-419c-aad4-14625b8ecf51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "73461dc9-2121-4c80-84df-4ce5a2e286d4", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "827a2576-50b1-4bc0-b67c-fafd4c845d16", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "b663b00a-4ef6-4738-96b2-a8f020fabf92", "text": "Igaz", "isCorrect": true}, {"id": "8ab17286-03cd-4a1e-99d8-dc75f4cb5b15", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "994e159a-7986-4cb4-b009-6c4068aad418", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('82de8e99-a5b6-4a16-ba8a-ed2240262762', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$116. óra: Feladatmegoldás$q$, $q$Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "29a3a42a-b223-4856-96bb-cb64e6ad0f6b", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "f1a9cae8-e919-4431-b924-43c8a9694fe0", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "33a082ad-c306-479e-b8c9-8f726e456808", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "eee3f7e4-fac3-45c1-a3b0-e74aa437e8f1", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "9c1e667e-04a6-4794-94e6-f27a9036e39d", "text": "Igaz", "isCorrect": true}, {"id": "3f68f658-1d9d-423d-8d01-212163bcab2d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "17838afc-7557-4372-90a2-262df6c4edad", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "38770473-9229-4448-9de8-fd8763030f0e", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "ca51065b-676a-4bdc-8ede-d985e37c8cdb", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "c9d570a1-0a96-4cea-9070-21f472612c23", "text": "Igaz", "isCorrect": true}, {"id": "4f773dc3-4c1d-4803-8613-d32ad5cd6ad5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('475928a8-8535-4574-b19d-f98c61616686', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$117. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "b7ec98fd-52d8-4b05-9e3d-12acc958b028", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "5de6f5fc-bb6f-4841-9e15-28e678ca661b", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "fd33cf1f-4f15-4105-a086-8423e3537fd8", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "f9da6281-957d-409f-a5f4-a527ff727ea5", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "c99ba47e-7888-43d4-af81-d3cb4ccaebf6", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "cf30a438-0106-4fcd-84f8-3061441ae8d1", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "bd313847-57ea-4710-8d69-8f02e4c4e8b6", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "ad1f992d-d0dc-4966-b024-f04e57f83616", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "cdb563de-fc74-45e7-adea-2cf51da7a9b7", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "eba1d100-d988-4781-86b0-216704cbaf8b", "text": "Igaz", "isCorrect": true}, {"id": "4a9f86d6-03e1-4ebf-bb89-efcb14ef1737", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b9f37cf-50f3-492f-93e7-61952ad9ad44", "text": "10. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3d644ffb-b643-4fb9-bd62-de4adee3f9a8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$118. óra: Témazáró dolgozat értékelése$q$, $q$A témazáró dolgozat megbeszélése és a mérések összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "abfd102b-eed4-444a-936c-285cdd5ebe34", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "d5306de7-df87-441b-a064-fa4ee2a64bce", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "556bc2c4-025b-4190-8c7d-b67e74df4f3f", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "fdb08ab4-5831-4ece-95d4-22a842621276", "text": "A számláló írása", "isCorrect": false}, {"id": "f7044615-0714-41d9-a444-a7188e36efdd", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "16446d02-1627-42d2-89d6-7a637aad17cd", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "a6695a59-8be7-4da9-be88-110330b2ddd3", "text": "Igaz", "isCorrect": true}, {"id": "d25d9a1c-e5fd-4c15-95a6-2d954564ba2d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "df775546-dac8-45a7-a265-c2edb317fea7", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "faac4530-c46e-4e53-b6c4-5b57721f8bf1", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "6821e2d0-aa02-4b99-8af5-7cd8821d6dfb", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "f9eee95d-188d-429b-88d7-8ab0672561f0", "text": "Igaz", "isCorrect": true}, {"id": "a6c7b654-03c2-4dad-b5ac-0bb424fc0625", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c015ea5-ecdf-4ded-a657-c9dd50695096", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "b4a0de3e-daea-4962-8242-ef5ee1270b1e", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "9923d6c9-db04-424e-8712-33d52811c4cb", "text": "Igaz", "isCorrect": true}, {"id": "67c14961-9f5b-47c2-8f93-481ffa243036", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a42f93e2-431f-4062-b51f-474e5ec7383a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$119. óra: Játék$q$, $q$Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "76d8fcdb-f08e-41e0-9586-577da285594c", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "f7d71abd-aef3-4e61-843a-d83cc0cc726d", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "0c8d5bc0-c893-40cf-b58f-57cea14933c0", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "d8f1f251-c610-4286-8983-ecd724f7dc87", "text": "Számok törlése", "isCorrect": false}, {"id": "e012026a-54c6-4078-8f96-eeae2ef0335c", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "28d36f04-7a2c-4b51-9a68-519c4edf1c09", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "29f66c2e-7614-4dd4-ae3e-c22378b63b17", "text": "Igaz", "isCorrect": true}, {"id": "87cf4eb7-70cf-442a-836a-c404bef1f5ee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4fff2079-09ea-4927-96b8-7ab309ba08fa", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "6ced0348-db38-46af-b66c-c019bfeb9081", "text": "Alvás", "isCorrect": true}, {"id": "fe552a43-6c5e-4c52-8014-7a8fa95afec8", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "9330ed2e-dce0-4e72-860d-9e4805c235a9", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "5ef80d41-8225-42a5-b18f-bd7b33e1e26e", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "2eb2abb7-c775-417f-afe7-5543bfadde77", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "71aadf4f-f661-4b9f-9a9c-21aaf0e8c70f", "text": "Igaz", "isCorrect": true}, {"id": "d586b2ae-d692-4339-ac91-c4d75383b298", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "00585595-ea5a-46e8-9e02-263d8a10aa19", "text": "Hány válaszlehetőség van egy 'igen/nem' típusú kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "f90b18e3-275a-4920-9bf6-b2d100ff6936", "text": "A statisztikai mintavétel során a cél a pontos és torzításmentes adatszerzés.", "type": "true-false", "options": [{"id": "f33115cb-f3aa-4b1c-be66-812602a6720c", "text": "Igaz", "isCorrect": true}, {"id": "b4ae06a0-4488-49bd-9791-0eceea27e8c2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fe664729-393b-4395-b4a5-dc9c8215beb6", "text": "Az adatok rendszerezése megkönnyíti a döntéshozatalt.", "type": "true-false", "options": [{"id": "9eb2ad4d-b531-49d9-8cba-0e9078a57d79", "text": "Igaz", "isCorrect": true}, {"id": "d29038fe-b673-4080-8833-76613608fe9e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d1f1dd98-a7a3-415f-8453-d34fd5d8eb29', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$120. óra: Grafikonok, diagramok, összefüggések$q$, $q$Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "33320bb9-9ecd-41eb-8895-a200f1a448fb", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "63feb18c-5f8b-4727-b9f0-5a11428ebfed", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "41442ded-02a4-4894-83ac-05180c00577c", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "eb10ee35-2d30-42fb-95b5-5f461d84c213", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "7e020b7e-c632-4227-b6d3-2cd5d8a6cad8", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "2d194217-271f-4b0d-b576-49c7eecd5fbf", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "dfcb07e6-710c-4891-988d-3c5205ca2ae7", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "ef0fe179-7e86-4262-952d-d994f184eb3e", "text": "Számok összeadására", "isCorrect": false}, {"id": "9a98c609-7e16-438d-bc56-48b5d08a01e9", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "d781e27d-d368-4a8d-b8c2-49a9c7f898f3", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "548f978b-9301-4aa1-8655-c096eff32099", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "3d379447-7f88-4c76-9ab1-ed188ac808e3", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "7f0f4701-1fe5-454b-8d72-29b9fcced10d", "text": "Igaz", "isCorrect": true}, {"id": "3dccfb74-6a23-46ab-934b-033bd1bd3620", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "125e55d1-2bcd-4ca5-b647-ae007ba84909", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "c66436d2-293b-4c30-a458-2ff02fa468d5", "text": "Igaz", "isCorrect": true}, {"id": "b9b71793-e1f5-41b1-a628-2c83086ff79a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "af50e4b0-d3cc-4fdf-b076-085f6409c6dd", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "fca10677-1920-458b-8322-bd058d7dc640", "text": "Igaz", "isCorrect": true}, {"id": "e45f40f2-0ce5-476a-bdb2-f65dc17c3ff7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8a80fd2-534a-4ce5-94b7-09917cf0f7c9", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;